window.LP.BookData[6] = {"n": 6, "title": "Big-M арга", "route": "bigm", "blocks": [{"t": "p", "x": "Симплекс аргын өргөтгөсөн бүлэг — ≥ ба = хязгаарлалттай бодлогуудын шийдэл"}, {"t": "h", "lvl": 2, "x": "6.1. Big-M аргын танилцуулга"}, {"t": "h", "lvl": 3, "x": "6.1.1. Big-M арга гэж юу вэ?"}, {"t": "p", "x": "Максимумчлах (Max) бодлого нь “Байгаа нөөцөөрөө хамгийн их ашгийг хэрхэн олох вэ?” гэсэн асуулт тавьдаг бол минимумчлах (Min) бодлого нь"}, {"t": "p", "x": "“Өгөгдсөн шаардлагыг хамгийн бага зардлаар хэрхэн хангах вэ?”"}, {"t": "p", "x": "гэсэн асуулт руу чиглэдэг тул эдийн засгийн хувьд тэс өөр логик шаарддаг."}, {"t": "p", "x": "Min бодлогод “их буюу тэнцүү” (≥) гэсэн хязгаарлалт орж ирдэг тул түүнийг энгийн симплекс аргаар шууд бодох боломжгүй. Ийм бодлогыг M-арга (Big-M Method) буюу их торгуулийн аргаар боддог. Уншигчид хамгийн ойлгомжтой байдаг хоолны дэглэмийн бодлогын (Diet Problem) жишээгээр бүрэн бодолтыг Бүлэг 6.6-д хийнэ."}, {"t": "p", "x": "Товчхондоо, Big-M арга бол Бүлэг 5-т үзсэн симплекс алгоритмын өргөтгөл юм. Энэ нь ≥ болон = хязгаарлалттай бодлогуудыг каноник хэлбэрт оруулж, дараа нь яг ижил симплекс процедураар бодох боломж олгодог. “M” үсэг нь маш том эерэг тоог буюу торгуулийг илэрхийлдэг бөгөөд түүний үүрэг бол зохиомол хувьсагчийг оновчтой шийдээс албадан хөөх явдал юм."}, {"t": "h", "lvl": 3, "x": "6.1.2. Хэзээ ашиглах вэ?"}, {"t": "p", "x": "Big-M аргыг дараах тохиолдолд ашигладаг:"}, {"t": "p", "x": "хязгаарлалтын систем дотор ≥ (их буюу тэнцүү) тэмдэгтэй хязгаарлалт байгаа үед;"}, {"t": "p", "x": "хязгаарлалтын систем дотор = (тэнцүү) тэмдэгтэй хязгаарлалт байгаа үед;"}, {"t": "p", "x": "ялангуяа Min буюу минимумчлах бодлогод, тухайлбал орц найрлагын буюу диетийн бодлогод (доод хязгаарын шаардлагатай тул ≥ хязгаарлалт байнга гарч ирдэг);"}, {"t": "p", "x": "Бүлэг 5-т үзсэн энгийн симплекс арга ажиллахгүй үед — өөрөөр хэлбэл гарааны симплекс хүснэгтэд бэлэн нэгж матриц (Identity Matrix) шууд үүсэхгүй байгаа тохиолдолд."}, {"t": "h", "lvl": 3, "x": "6.1.3. Яагаад Big-M нэр өгсөн вэ?"}, {"t": "p", "x": "“M” гэдэг нэр нь торгуулийн хэмжээг илэрхийлэх маш том тооноос гаралтай. Практикт M-ийг бодлогын бусад бүх коэффициентээс хэдэн зуу, хэдэн мянга дахин том байхаар сонгодог. Зохиомол хувьсагч Aᵢ нь зорилгын функцэд +M (Min бодлогод) эсвэл −M (Max бодлогод) коэффициенттэйгээр орж ирдэг тул тухайн хувьсагчийг эерэг утгатай (0-ээс их) орхих нь симплекс алгоритмын хувьд маш ашиггүй буюу маш өндөр өртөгтэй сонголт болдог."}, {"t": "p", "x": "Улмаар алгоритм өөрөө Aᵢ хувьсагчийг аль болох хурдан 0 болгохыг автоматаар эрмэлздэг — яг л мөнгөн торгууль хүлээсэн хүн түүнээсээ аль болох хурдан ангижрахыг хичээдэгтэй адил. Энэ зарчмаас улбаалж уг аргыг торгуулийн арга (Penalty Method) гэж бас нэрлэдэг."}, {"t": "h", "lvl": 3, "x": "6.1.4. Симплекс аргатай уялдаа"}, {"t": "p", "x": "Big-M = симплекс + тусгай эхлэл."}, {"t": "p", "x": "Бүлэг 5-т үзсэн симплекс алгоритмын үндсэн логик (орох баганыг сонгох, гарах мөрийг тодорхойлох, ялгагч элементээр хүснэгтийг шинэчлэх) Big-M аргад яг хэвээрээ хэрэглэгдэнэ. Зөвхөн нэг зүйл өөр байдаг — гарааны симплекс хүснэгтийг хэрхэн байгуулах вэ гэдэг асуудал."}, {"t": "p", "x": "Бүлэг 5.2-т “Модон урлал” ХХК-ийн жишээнд зөвхөн ≤ хязгаарлалт байсан тул нэмэлт хувьсагчид (+S) шууд суурь (Basic) хувьсагч болж, гарааны хүснэгт цэвэр нэгж матрицтай эхэлж байсан. Харин ≥ болон = хязгаарлалттай үед ийм бэлэн суурь автоматаар үүсдэггүй тул зохиомол хувьсагч (+A) ашиглан суурийг зохиомлоор бүрдүүлдэг."}, {"t": "p", "x": "Иймд Бүлэг 5-ыг сайн ойлгосон уншигчид энэ бүлэг логик үргэлжлэл болно: симплекс алгоритм “яаж ажилладаг” тал нь өөрчлөгдөхгүй, зөвхөн “хаанаас эхэлдэг” тал нь өөрчлөгдөнө."}, {"t": "h", "lvl": 2, "x": "6.2. Каноник хэлбэрийн алгебр"}, {"t": "p", "x": "Энэ хэсэг бол Big-M аргын гол цөм юм. Хязгаарлалтын төрөл бүрд тохирсон хувиргалт хийж бодлогыг каноник хэлбэрт оруулна — энэ бол тодорхой дүрэмтэй, алгебрын шинжтэй үйлдэл."}, {"t": "h", "lvl": 3, "x": "6.2.1. Каноник хэлбэрийн шаардлага"}, {"t": "table", "rows": [["Шинж чанар", "Ерөнхий хэлбэр", "Стандарт хэлбэр", "Каноник хэлбэр"], ["Зорилго", "Max / Min", "Max", "Max / Min"], ["Хязгаарлалт", "=, ≤, ≥", "Зөвхөн ≤", "Зөвхөн ="], ["Хувьсагч", "Дурын", "x ≥ 0", "x ≥ 0"], ["Хэрэглээ", "Бодлогын тавилт", "График арга, хосмог онол", "Симплекс арга (компьютерийн тооцоолол)"]]}, {"t": "p", "x": "Каноник хэлбэрийн шаардлагыг дүгнэвэл:"}, {"t": "p", "x": "бүх хязгаарлалт тэгшитгэл (=) хэлбэртэй байна;"}, {"t": "p", "x": "бүх хувьсагч ≥ 0 байна (үл сөрөг байх нөхцөл);"}, {"t": "p", "x": "зорилгын функц Max эсвэл Min аль ч хэлбэртэй байж болно — Big-M аргад үүнийг M-ийн тэмдгээр зохицуулдаг (Бүлэг 6.4.3-т үзнэ);"}, {"t": "p", "x": "энэ бол симплекс арга буюу компьютерийн тооцоолол шаарддаг цорын ганц хэлбэр."}, {"t": "h", "lvl": 3, "x": "6.2.2. ≤ хязгаарлалт → +S (нэмэлт хувьсагч)"}, {"t": "p", "x": "Энэ хувиргалтыг Бүлэг 5.2-т “Модон урлал” ХХК-ийн жишээгээр аль хэдийн дэлгэрэнгүй үзсэн. Сануулбал:"}, {"t": "p", "x": "“Компьютер тэнцэтгэл бишийг (≤) ойлгодоггүй тул бид түүнийг тэгшитгэл (=) болгох ёстой. Үүний тулд нэмэлт хувьсагч (Slack variable – s) нэмнэ.”"}, {"t": "p", "x": "Ерөнхий хэлбэр:"}, {"t": "p", "x": "a₁x₁ + a₂x₂ ≤ b"}, {"t": "p", "x": "Каноник хэлбэрт:"}, {"t": "p", "x": "a₁x₁ + a₂x₂ + s = b   (s ≥ 0)"}, {"t": "p", "x": "Тайлбар: “s” бол ашиглагдаагүй үлдэгдэл. Тэнцэтгэл бишийг тэгшитгэл болгоход s ≥ 0 гэсэн нөхцөл дагалдана."}, {"t": "p", "x": "Жишээ: 4x₁ + 2x₂ ≤ 100  →  4x₁ + 2x₂ + s₁ = 100 (“Модон урлал” ХХК-ийн жишээ, Бүлэг 5.2-т үзсэн)."}, {"t": "h", "lvl": 3, "x": "6.2.3. ≥ хязгаарлалт → −S + A (илүүдэл ба зохиомол хувьсагч)"}, {"t": "p", "x": "Энэ бол Бүлэг 6-д шинээр зааж буй хамгийн чухал алгебр юм."}, {"t": "p", "x": "Ерөнхий хэлбэр:"}, {"t": "p", "x": "a₁x₁ + a₂x₂ ≥ b"}, {"t": "p", "x": "Алхам 1. Илүүдэл хувьсагчийг хасна."}, {"t": "p", "x": "a₁x₁ + a₂x₂ − s = b   (s ≥ 0)"}, {"t": "p", "x": "Тайлбар: “s” бол шаардлагаас илүү гарсан хэмжээ. Түүнийг нэмэхгүй, харин хасна: бодит утга шаардлагаас дээш давсан тохиолдолд хоёр талыг тэнцүүлэхийн тулд илүүдлийг хасах шаардлагатай болдог."}, {"t": "p", "x": "Асуудал: симплекс алгоритм эхлэхэд суурь хувьсагчийн утга сөрөг биш байх ёстой. Гэвч x₁ = x₂ = 0 үед −s = b > 0 болох тул s = −b < 0 буюу сөрөг гарна (энэ нь боломжгүй). Иймд “s”-ийг шууд суурь болгож эхлэх боломжгүй."}, {"t": "p", "x": "Алхам 2. Зохиомол хувьсагч нэмнэ."}, {"t": "p", "x": "a₁x₁ + a₂x₂ − s + A = b   (s, A ≥ 0)"}, {"t": "p", "x": "Тайлбар: “A” бол зохиомол хувьсагч. Энэ нь симплекс алгоритмыг эхлүүлэхэд шаардлагатай ч, оновчтой шийдэд A = 0 байх ёстой (Бүлэг 6.3.3-т дэлгэрэнгүй)."}, {"t": "p", "x": "Жишээ: 2x₁ + 3x₂ ≥ 12  →  2x₁ + 3x₂ − s + A = 12"}, {"t": "h", "lvl": 3, "x": "6.2.4. = хязгаарлалт → +A (зохиомол хувьсагч)"}, {"t": "p", "x": "Ерөнхий хэлбэр:"}, {"t": "p", "x": "a₁x₁ + a₂x₂ = b"}, {"t": "p", "x": "Каноник хэлбэрт:"}, {"t": "p", "x": "a₁x₁ + a₂x₂ + A = b   (A ≥ 0)"}, {"t": "p", "x": "Тайлбар: хязгаарлалт нь аль хэдийн тэгшитгэл байгаа тул сул ч, илүүдэл ч хувьсагч огт шаардлагагүй — симплекс аргыг эхлүүлэхэд зайлшгүй хэрэгтэй зохиомол хувьсагч л нэмэгдэнэ."}, {"t": "p", "x": "Жишээ: 3x₁ + 2x₂ = 15  →  3x₁ + 2x₂ + A = 15"}, {"t": "h", "lvl": 3, "x": "6.2.5. Гурван төрлийн хувьсагчийн хураангуй"}, {"t": "table", "rows": [["Хязгаарлалтын тэмдэг", "Нэмэгдэх хувьсагч", "Тэмдэг"], ["≤ (бага буюу тэнцүү)", "Нэмэлт хувьсагч (Slack)", "+S"], ["≥ (их буюу тэнцүү)", "Илүүдэл хувьсагч (Surplus) + зохиомол хувьсагч (Artificial)", "−S  болон  +A"], ["= (тэнцүү)", "Зохиомол хувьсагч (Artificial)", "+A"]]}, {"t": "h", "lvl": 3, "x": "6.2.6. Алгебрын зайлшгүй шаардлага"}, {"t": "p", "x": "Тэнцэтгэл бишийг тэгшитгэл болгох нь симплекс алгоритмын математик урьдчилсан нөхцөл юм (Бүлэг 5-т үзсэнчлэн алгоритм зөвхөн тэгшитгэлт систем дээр Гаусс-Жорданы мөрийн үйлдэл хийдэг). Каноник хэлбэр бол зүгээр нэг тэмдэглэгээний хувиргалт биш — энэ бол компьютерийн тооцоолол хийх боломжийг нээж өгдөг алгебрын урьдчилсан нөхцөл юм. Энэ ойлголтыг сайн эзэмшсэн уншигч Big-M аргын бусад бүх алхмыг хялбар дагах болно."}, {"t": "h", "lvl": 2, "x": "6.3. Хувьсагчдын эдийн засгийн утга"}, {"t": "p", "x": "Гурван төрлийн хувьсагч тус бүр өөр өөр практик утгатай. Уншигчид ялангуяа “−S” ба “+A” хоёрыг андуурч болзошгүй тул тэдгээрийн ялгааг доор тодорхой тайлбарлав."}, {"t": "h", "lvl": 3, "x": "6.3.1. Нэмэлт хувьсагч (+S) — Slack"}, {"t": "p", "x": "Хэзээ ашигладаг вэ? Боломжит нөөцийн дээд хязгаар буюу “бага буюу тэнцүү” (≤) хязгаарлалтад нэмэгдэж ордог. (Жишээ нь: 2x₁ + 3x₂ + S = 100)"}, {"t": "p", "x": "Эдийн засгийн утга: энэ бол компанийн үлдэгдэл нөөц, ашиглагдаагүй хүчин чадал буюу сул зогсолт юм."}, {"t": "p", "x": "Менежерийн өнцгөөс: эцсийн шийд дээр S > 0 гарвал энэ нь тухайн нөөц (мод, цахилгаан, ажилчдын цаг гэх мэт) бүрэн ашиглагдаж дуусаагүй, агуулахад илүүдэл байдлаар үлдсэн гэсэн үг. Ийм нөөц нь хязгаарлагч хүчин зүйл (Bottleneck) биш учраас түүнийг нэмж худалдан авах шаардлагагүй (сүүдрийн үнэ нь 0 байна)."}, {"t": "p", "x": "Жишээ: ажилчдын 100 цагийн фонд байснаас төлөвлөгөөгөө 80 цагт багтаан гүйцэтгэвэл S = 20 цаг болно. Энэ 20 цаг бол бидний сул үлдсэн (Slack) нөөц юм."}, {"t": "p", "x": "→ Дэлгэрэнгүйг Бүлэг 5.2-т үзсэн."}, {"t": "h", "lvl": 3, "x": "6.3.2. Илүүдэл хувьсагч (−S) — Surplus"}, {"t": "p", "x": "Хэзээ ашигладаг вэ? Заавал биелүүлэх доод хязгаар буюу “их буюу тэнцүү” (≥) хязгаарлалтаас хасагдаж ордог. (Жишээ нь: x₁ + x₂ − S = 40)"}, {"t": "p", "x": "Эдийн засгийн утга: энэ бол төлөвлөгөөний давалт буюу шаардлагаас давсан илүүдэл юм."}, {"t": "p", "x": "Менежерийн өнцгөөс: эцсийн шийд дээр S > 0 гарвал байгууллага тавигдсан доод стандартыг давуулан биелүүлсэн гэсэн үг. Жишээ нь малын тэжээлд доод тал нь 40 грамм уураг байх шаардлагатай байсан ч, хамгийн хямд орцын холимог хийхэд санамсаргүйгээр 45 грамм уурагтай болж болно."}, {"t": "p", "x": "Жишээ: дээрх тохиолдолд −S = −5, өөрөөр хэлбэл S = 5 бөгөөд стандарт шаардлагаас 5 грамм уургаар илүү (Surplus) гарсан байна. Энэ нь муу зүйл биш, зөвхөн доод хязгаараас давсан гэдгийг харуулна."}, {"t": "h", "lvl": 3, "x": "6.3.3. Зохиомол хувьсагч (+A) — “жинхэнэ” хувьсагч биш"}, {"t": "p", "x": "Хэзээ ашигладаг вэ? “Их буюу тэнцүү” (≥) эсвэл шууд “тэнцүү” (=) хязгаарлалттай үед эхний шийдийг олохын тулд албадан нэмдэг. (Жишээ нь: x₁ + x₂ − S + A = 40)"}, {"t": "p", "x": "Эдийн засгийн утга: энэ бол байгууллагыг албадан ажиллуулахын тулд гаднаас авч буй хүчтэй оролцоо, өндөр үнэтэй онцгой арга хэмжээ буюу торгууль юм. Практикт ямар ч бодит утга агуулдаггүй — энэ бол зөвхөн симплекс алгоритмыг эхлүүлэх математикийн хэрэглүүр."}, {"t": "p", "x": "Менежерийн өнцгөөс: симплекс арга анх эхлэхдээ хаанаас эхлэхээ мэддэггүй тул хамгийн хялбар замаар, энэхүү зохиомол (Artificial) нөөцийг ашиглан стандартыг түр хангадаг. Гэхдээ энэ нөөц маш өндөр өртөгтэй (Big-M торгуультай) учраас менежер аль болох хурдан зохиомол аргаас салж, бодит бүтээгдэхүүнээрээ шаардлагыг хангахыг эрмэлздэг."}, {"t": "p", "x": "Сөрөг үр дагавар: бодолт дуусахад A > 0 хэвээр үлдвэл эдийн засгийн маш ноцтой асуудал үүснэ. Энэ нь “компани өөрийн бодит нөөцөөрөө энэ зорилтод хүрч чадахгүй, систем шийдгүй байдалд оржээ (Infeasible)” гэсэн хатуу оношийг тавьж байгаа хэрэг юм."}, {"t": "table", "rows": [["Хувьсагч", "Үйлдэл", "Үүсэх нөхцөл", "Эдийн засгийн утга санаа", "Эцсийн шийдэд байвал сайн уу?"], ["+S (Slack)", "Нэмнэ (+)", "≤", "Ашиглагдаагүй үлдсэн нөөц, сул зогсолт.", "Хэвийн. Тухайн нөөц илүүдэлтэй байна гэсэн үг."], ["−S (Surplus)", "Хасна (−)", "≥", "Шаардлагыг давуулан биелүүлсэн илүүдэл.", "Хэвийн. Стандартаас давсан үзүүлэлт."], ["+A (Artificial)", "Нэмнэ (+)", "≥ болон =", "Анхны тэнцвэрийг олохын тулд гаднаас оруулсан өндөр өртөгт торгууль.", "Тааруу. Хэрэв эцэст нь үлдвэл бодлого шийдгүй."]]}, {"t": "h", "lvl": 2, "x": "6.4. M — торгуулийн систем"}, {"t": "h", "lvl": 3, "x": "6.4.1. Яагаад M маш том тоо вэ?"}, {"t": "p", "x": "Зохиомол хувьсагчийг оновчтой шийдэд орохгүй байхаар албадах нь Big-M аргын гол зорилго юм. Тэрхүү хувьсагчид зорилгын функцэд маш өндөр торгууль тавьснаар симплекс алгоритм ашгаа өсгөх (эсвэл зардлаа бууруулах) гэсэн байгалийн зорилгынхоо дагуу A-г автоматаар 0 болгохыг эрмэлздэг."}, {"t": "h", "lvl": 3, "x": "6.4.2. M-ийн үнэ цэнэ"}, {"t": "p", "x": "Математикийн хувьд: M → ∞ (хязгааргүй том тоо)."}, {"t": "p", "x": "Практикт: тооцоолол хийхдээ 1 000, 10 000, 100 000 гэх мэт, бодлогын бусад бүх коэффициентээс мэдэгдэхүйц том тоо ашигладаг (Excel Solver зэрэг программ ийм том тоог автоматаар оноодог)."}, {"t": "p", "x": "Дүрэм: M нь бодлогын аль ч коэффициентээс хамаагүй том байх ёстой — эс тэгвээс алгоритм Aᵢ-г бүрэн хөөж чадахгүй байж болзошгүй."}, {"t": "h", "lvl": 3, "x": "6.4.3. Max ба Min бодлогод M-ийн тэмдэг"}, {"t": "table", "rows": [["Анхааруулга. M-ийн тэмдэг Min ба Max бодлогод эсрэг байна.\nMin бодлого: +M·A (эерэг тэмдэг). Зардлыг минимумчлах гэж байгаа тул A > 0 бол нийт зардал +M·A-гаар асар ихээр өснө. Тиймээс симплекс алгоритм A-г 0 болгохыг эрмэлзэнэ. Жишээ: Z = 5x₁ + 3x₂ + MA₁ + MA₂ → min (Бүлэг 6.6-гийн “Хиам” ХХК-ийн жишээ).\nMax бодлого: зорилгын функцэд −M·A (сөрөг тэмдэг). Ашгийг максимумчлах гэж байгаа тул A > 0 бол нийт ашиг −M·A-гаар асар ихээр буурна. Тиймээс симплекс алгоритм A-г 0 болгохыг эрмэлзэнэ. Жишээ: Z = 40x₁ + 30x₂ − MA₁ → max.\nТовч дүрэм: M-ийн тэмдэг хамгийн их торгох чиглэлд байх ёстой — Min бодлогод торгууль “+M” (зардлыг өсгөнө), Max бодлогод торгууль “−M” (ашгийг бууруулна)."]]}, {"t": "h", "lvl": 3, "x": "6.4.4. M-ийг симплекс хүснэгтэд харуулах"}, {"t": "p", "x": "Симплекс хүснэгтийн Z мөрөнд M-ийг бэлгэдлийн хэлбэрээр (жишээ нь 3M − 5 гэх мэт) хадгалж, тооцооллыг M-ийн коэффициент болон энгийн тогтмол гэсэн хоёр хэсэгт хувааж хийдэг (Бүлэг 6.6-д дэлгэрэнгүй харуулна). Бодит тооцоололд, тухайлбал компьютерийн программ дээр M-д ердийн том тоо (1000 гэх мэт) оноож болно."}, {"t": "h", "lvl": 2, "x": "6.5. Big-M алгоритмын дэс дараалал"}, {"t": "p", "x": "Дараах зургаан алхам нь Бүлэг 6.6-д “Хиам” ХХК-ийн жишээгээр бүрэн харуулах Big-M бодолтын ерөнхий схем юм."}, {"t": "h", "lvl": 3, "x": "6.5.1. Алхам 1. Каноник хэлбэрт оруулах"}, {"t": "p", "x": "Хязгаарлалтын төрөл бүрд тохирсон хувьсагч нэмнэ (Бүлэг 6.2-т үзсэнчлэн): ≤ хязгаарлалтад +S, ≥ хязгаарлалтад −S болон +A, = хязгаарлалтад +A нэмнэ."}, {"t": "h", "lvl": 3, "x": "6.5.2. Алхам 2. Зорилгын функцийг шинэчлэх"}, {"t": "p", "x": "Зохиомол хувьсагч бүрийг зорилгын функцэд M коэффициенттэйгээр оруулна:"}, {"t": "p", "x": "Max бодлогод: Z − ... − MA₁ − MA₂ − ... → max"}, {"t": "p", "x": "Min бодлогод: Z + ... + MA₁ + MA₂ + ... → min"}, {"t": "h", "lvl": 3, "x": "6.5.3. Алхам 3. Анхны симплекс хүснэгт байгуулах"}, {"t": "p", "x": "Суурь хувьсагчаар зохиомол хувьсагчид (A₁, A₂, ...) болон нэмэлт хувьсагчдыг (s₁, s₂, ... — зөвхөн ≤ хязгаарлалтаас гарсныг) авна. Илүүдэл хувьсагчид (−s) эхлээд суурь бус (Non-basic) байна."}, {"t": "h", "lvl": 3, "x": "6.5.4. Алхам 4. Z мөрийг тэгшлэх"}, {"t": "p", "x": "Зохиомол хувьсагч Z мөрөнд M коэффициенттэй боловч, анхны хүснэгтэд A-гийн харгалзах баганад заавал 0 байх ёстой (учир нь A нь суурь хувьсагч). Тиймээс мөрийн үйлдэл хийж Z мөрийг шинэчилдэг. Практикт үүнийг симплекс хүснэгтийн стандарт томьёогоор тооцоолдог:"}, {"t": "p", "x": "Zⱼ − Cⱼ = ∑(Cᵦ × aᵢⱼ) − Cⱼ"}, {"t": "p", "x": "Cᵦ: суурь хувьсагчдын зорилгын функц дэх коэффициент (эхний хүснэгтэд эдгээр нь голдуу M байдаг)"}, {"t": "p", "x": "aᵢⱼ: тухайн баганад байгаа тоонууд"}, {"t": "p", "x": "Cⱼ: тухайн хувьсагчийн өөрийнх нь зорилгын функц дэх анхны коэффициент (нэгжийн ашиг эсвэл зардал)"}, {"t": "p", "x": "Практикт: Z мөрийг тэгшилснээр M коэффициент бусад баганад дамжина. Тэдгээр коэффициент нь орох баганыг сонгоход шийдвэрлэх нөлөөтэй байдаг."}, {"t": "h", "lvl": 3, "x": "6.5.5. Алхам 5. Симплекс алгоритмыг ажиллуулах"}, {"t": "p", "x": "Эндээс цааш Бүлэг 5-т сурсан симплекс аргаар яг хэвээрээ ажиллана:"}, {"t": "p", "x": "Орох багана: Бүлэг 5.4.1-т үзсэнчлэн сонгоно (Max бодлогод хамгийн сөрөг, Min бодлогод хамгийн эерэг Z мөрийн утга — M-ийн коэффициентийг эхлээд харьцуулна)."}, {"t": "p", "x": "Гарах мөр: Бүлэг 5.4.2-т үзсэнчлэн хамгийн бага харьцаагаар (Minimum Ratio Test) сонгоно."}, {"t": "p", "x": "Ялгагч элемент ба мөрийн үйлдэл: Бүлэг 5.4.5-т үзсэн Гаусс-Жорданы аргаар яг адилхан хийнэ."}, {"t": "h", "lvl": 3, "x": "6.5.6. Алхам 6. Бодолтыг дуустал үргэлжлүүлэх"}, {"t": "p", "x": "Оновчлолын нөхцөл хангагдтал (Max бодлогод Z мөрөнд сөрөг тоо байхгүй болтол, Min бодлогод Z мөрөнд эерэг тоо байхгүй болтол) итерацийг үргэлжлүүлнэ."}, {"t": "table", "rows": [["Тусгай шалгалт. Бүх A = 0 байх ёстой.\nОновчтой шийд олдсоны дараа суурьт (Basic) ямар ч зохиомол хувьсагч A > 0 утгатай үлдэж болохгүй. Хэрэв бодолт дуусахад Aᵢ > 0 хэвээр байвал — тухайлбал энэ хувьсагч суурьт үлдэж, оновчтой хүснэгтийн мөрөнд эерэг утгатай гарвал — бодлого шийдгүй (Infeasible) гэсэн үг. Ийм үед тавигдсан шаардлагыг бодит нөөцөөр хангах боломжгүй гэдгийг илтгэнэ (Дасгал 8-д энэ тохиолдлыг дадлагажина)."]]}, {"t": "h", "lvl": 2, "x": "6.6. Гол жишээ: “Хиам” ХХК-ийн бүрэн Big-M шийдэл"}, {"t": "p", "x": "Бүлэг 2.8.1-т тавилтыг нь хийсэн бодлогыг эндээс бүрэн шийднэ. Энэ бол “Модон урлал” ХХК-ийн жишээтэй адил, энэ бүлгийн гол жишээ бөгөөд Big-M аргын бүх алхмыг үзүүлнэ."}, {"t": "h", "lvl": 3, "x": "6.6.1. Бизнесийн нөхцөл (сануулга)"}, {"t": "p", "x": "Бүлэг 2.8.1-т тавьсан “Хиам” ХХК-ийн орц найрлагын бодлогыг эндээс Big-M аргаар бүрэн шийднэ."}, {"t": "p", "x": "Нөхцөл байдал: тус компани уураг, төмрөөр баялаг эрүүл мэндийн хиам үйлдвэрлэдэг. Хиамны таташ нь үхрийн мах (x₁) болон тахианы цээж мах (x₂)-наас бүрдэнэ."}, {"t": "p", "x": "Үхрийн махны үнэ: 5,000₮/кг (C₁ = 5)"}, {"t": "p", "x": "Тахианы махны үнэ: 3,000₮/кг (C₂ = 3)"}, {"t": "p", "x": "Эрүүл ахуйн стандартын шаардлага (нэг багц хиаманд байх доод хязгаар):"}, {"t": "p", "x": "Уураг: хамгийн багадаа 10 нэгж байна. (1 кг үхрийн маханд 1 нэгж, 1 кг тахианы маханд 2 нэгж уураг байдаг.)"}, {"t": "p", "x": "Төмөр: хамгийн багадаа 8 нэгж байна. (1 кг үхрийн маханд 2 нэгж, 1 кг тахианы маханд 1 нэгж төмөр байдаг.)"}, {"t": "h", "lvl": 3, "x": "6.6.2. Бодлогын тавилт (сануулга)"}, {"t": "p", "x": "Хувьсагч: x₁ = үхрийн мах (кг), x₂ = тахианы мах (кг)"}, {"t": "p", "x": "Z = 5x₁ + 3x₂ → min"}, {"t": "p", "x": "Хязгаарлалт:"}, {"t": "p", "x": "1x₁ + 2x₂ ≥ 10   (уураг)"}, {"t": "p", "x": "2x₁ + 1x₂ ≥ 8   (төмөр)"}, {"t": "p", "x": "x₁, x₂ ≥ 0"}, {"t": "h", "lvl": 3, "x": "6.6.3. Каноник хэлбэрт оруулах"}, {"t": "p", "x": "≥ (их буюу тэнцүү) тэмдэгтэй хязгаарлалтыг тэгшитгэл болгохын тулд хоёр төрлийн хувьсагч нэмдэг. Тэдгээрийн эдийн засгийн утгыг дараах байдлаар тайлбарлаж болно:"}, {"t": "p", "x": "Илүүдэл хувьсагч (s₁, s₂): энэ бол хэрэглэгчид үнэгүй өгч буй шим тэжээл юм. Стандарт нь 10 нэгж уураг нэхэж байхад бид 12 нэгжийг хийвэл 2 нэгж илүүдэл (s₁) гарна. Хэрэглэгч үүнд илүү мөнгө төлөхгүй тул компанийн хувьд үргүй зардал болно."}, {"t": "p", "x": "Зохиомол хувьсагч (A₁, A₂) ба торгууль: эхлээд ямар ч мах хийгээгүй (0) байхад тэгшитгэл тэнцэхгүй. Тиймээс “хуурамч химийн орц” (A₁, A₂) хийж стандартыг түр хангаж байна гэж төсөөлье. Гэтэл эрүүл ахуйн байцаагч үүнийг илрүүлээд маш их хэмжээний мөнгөн торгууль (M) тавина."}, {"t": "p", "x": "Шинэчилсэн загвар:"}, {"t": "p", "x": "1x₁ + 2x₂ − s₁ + A₁ = 10"}, {"t": "p", "x": "2x₁ + 1x₂ − s₂ + A₂ = 8"}, {"t": "p", "x": "Зорилго:  Z = 5x₁ + 3x₂ + MA₁ + MA₂ → min"}, {"t": "h", "lvl": 3, "x": "6.6.4. Анхны симплекс хүснэгт"}, {"t": "p", "x": "Алгоритмын зорилго: Z мөрөнд байгаа хамгийн өндөр эерэг тоог арилгах явдал юм. Загварын хувьд M торгууль хэт өндөр тул алгоритм түүнээс хамгийн хурдан салгаж чадах орцыг хайна."}, {"t": "table", "rows": [["Суурь", "x₁ (үхэр)", "x₂ (тахиа)", "s₁", "s₂", "Шийд (RHS)", "Харьцаа"], ["A₁ (торгууль 1)", "1", "2", "−1", "0", "10", "10/2 = 5"], ["A₂ (торгууль 2)", "2", "1", "0", "−1", "8", "8/1 = 8"], ["Z (зардал)", "3M − 5", "3M − 3", "−M", "−M", "18M", ""]]}, {"t": "p", "x": "Эдийн засгийн тайлбар: одоогоор бид зөвхөн “хуурамч орц”-оор хиам хийгээд 18M буюу асар их торгууль хүлээж байна. Z мөрөнд x₂ (тахиа) нь 3M − 3 гэсэн хамгийн өндөр эерэг утгатай байна. Яагаад вэ? Учир нь тахианы мах уураг ихтэй (2 нэгж), түүнчлэн хямд (3,000₮) учраас биднийг эхний торгуулиас хамгийн хурдан аварч чадна."}, {"t": "p", "x": "Үйлдэл: тахианы мах (x₂) суурьт орж, уургийн торгууль (A₁) гарна. Гол элемент 2."}, {"t": "p", "x": "Z мөрийн тооцооллын томьёо"}, {"t": "p", "x": "Симплекс хүснэгтийн хамгийн доод талын Z мөр буюу Zⱼ − Cⱼ (зарим сурах бичигт Δⱼ гэж тэмдэглэдэг)-ийг олох томьёо нь:"}, {"t": "p", "x": "Zⱼ − Cⱼ = ∑(Cᵦ × aᵢⱼ) − Cⱼ"}, {"t": "p", "x": "Cᵦ: суурь хувьсагчдын зорилгын функц дэх коэффициент (эхний хүснэгтэд эдгээр нь голдуу M байдаг)"}, {"t": "p", "x": "aᵢⱼ: тухайн баганад байгаа тоонууд"}, {"t": "p", "x": "Cⱼ: тухайн хувьсагчийн өөрийнх нь зорилгын функц дэх анхны коэффициент (нэгжийн зардал)"}, {"t": "p", "x": "Тоонуудыг хэрхэн гаргаж ирсэн бэ? (Задаргаа)"}, {"t": "p", "x": "Анхны зорилгын функц нь Z = 5x₁ + 3x₂ байсан. Одоо Z мөрийн тоонуудыг хэрхэн бодсоныг задалъя:"}, {"t": "p", "x": "3M − 5 хэрхэн гарсан бэ? (x₁ дээр)"}, {"t": "p", "x": "x₁-ийн анхны коэффициент нь C₁ = 5 байсан."}, {"t": "p", "x": "x₁ баганад байрлах хязгаарлалтын коэффициентүүдийн нийлбэр нь 3 байна."}, {"t": "p", "x": "Тооцоолол: суурьт байгаа зохиомол хувьсагчдын M торгуулийг баганын нийлбэрээр үржүүлээд, анхны коэффициентийг нь хасна: (M × 3) − 5 = 3M − 5."}, {"t": "p", "x": "3M − 3 хэрхэн гарсан бэ? (x₂ дээр)"}, {"t": "p", "x": "x₂-ийн анхны коэффициент нь C₂ = 3 байсан."}, {"t": "p", "x": "x₂ баганад байрлах коэффициентүүдийн нийлбэр бас л 3 байна."}, {"t": "p", "x": "Тооцоолол: (M × 3) − 3 = 3M − 3."}, {"t": "p", "x": "−M хэрхэн гарсан бэ? (илүүдэл хувьсагчид дээр)"}, {"t": "p", "x": "Хязгаарлалтын тэгшитгэлд ≥ тэмдэг байсан учраас хасах тэмдэгтэй илүүдэл хувьсагч (Surplus variable) орж ирсэн. Тэдгээрийн баганын нийлбэр нь −1, харин анхны коэффициент нь 0 байдаг."}, {"t": "p", "x": "Тооцоолол: (M × (−1)) − 0 = −M."}, {"t": "p", "x": "18M хэрхэн гарсан бэ? (нийт торгуулийн зардал буюу Z-ийн утга)"}, {"t": "p", "x": "Энэ бол хамгийн баруун захын багана буюу шийдийн (RHS) хэсэг юм."}, {"t": "p", "x": "Хязгаарлалтын тэгшитгэлүүдийн баруун гар талд байсан чөлөөт гишүүдийн нийлбэр нь 18 байна."}, {"t": "p", "x": "Тооцоолол: гарааны үед бид ямар ч бодит бүтээгдэхүүн үйлдвэрлээгүй, зөвхөн зохиомол хувьсагчтай байгаа тул 18 нэгжийн хэмжээгээр торгуульд орж байна гэсэн үг: (M × 18) = 18M."}, {"t": "h", "lvl": 3, "x": "6.6.5. Z мөрийг тэгшлэх — орох ба гарах хувьсагчийг сонгох логик"}, {"t": "p", "x": "Багана сонгох: бид үнэндээ багыг нь биш, ихийг нь сонгосон."}, {"t": "p", "x": "Min буюу зардал бууруулах бодлогын үед Z мөрөнд x₁ нь 3M − 5, x₂ нь 3M − 3 гэсэн утгатай байв. Эндээс бид хамгийн их эерэг тоо болох 3M − 3-тай тахианы махны (x₂) баганыг сонгосон."}, {"t": "p", "x": "Эдийн засгийн утга: торгууль (M) асар өндөр байгаа үед тахианы мах уураг ихтэй тул биднийг торгуулиас хамгийн хурдан салгаж чадах хамгийн ашигтай орц болж байна. Тиймээс хамгийн хүчтэй нөлөөлөх хувьсагчийг оруулж ирсэн."}, {"t": "p", "x": "Мөр сонгох: яагаад заавал хамгийн бага харьцааг (Minimum Ratio) сонгодог вэ?"}, {"t": "p", "x": "Тахианы махыг (x₂) хэдий хэмжээгээр хийхээ шийдэхийн тулд шийдийн (RHS) баганыг хувааж харьцаа гаргасан:"}, {"t": "p", "x": "Уургийн (A₁) мөрөнд:  10/2 = 5"}, {"t": "p", "x": "Төмрийн (A₂) мөрөнд:  8/1 = 8"}, {"t": "p", "x": "Эндээс хамгийн бага тоо болох 5-ыг сонгож, уургийн торгуулийг (A₁) эхэлж арилгасан. Яагаад 8-ыг сонгож болоогүй вэ?"}, {"t": "p", "x": "Эдийн засгийн учир шалтгаан (Bottleneck зарчим): хамгийн бага харьцааг сонгох дүрэм бол эдийн засаг, үйлдвэрлэлийн аюулгүйн хавхлага (Safety Limit) юм."}, {"t": "p", "x": "Хэрэв бид 8-ыг буюу их тоог сонгосон бол юу болох байсан бэ? Төмрийн шаардлагыг бүрэн хангахын тулд 8 кг тахианы мах хийнэ гэсэн үг. 8 кг тахианы маханд төмөр 8 нэгж (8 × 1) байх тул уг шаардлага биелнэ. Гэтэл тэр 8 кг тахианы маханд уураг нь 16 нэгж (8 × 2) болно. Уургийн хязгаарлалт нь зохиомол хувьсагчийн хамт яг 10 дээр тэнцэх ёстой тэгшитгэл байсан тул 16 нэгж уураг оруулбал систем задарч, хувьсагчид сөрөг утгатай болж эхэлнэ. Эдийн засгийн хувьд энэ нь “хэтрүүлэн хэрэглэж, системийн тэнцвэрийг эвдсэн” хэрэг болно."}, {"t": "p", "x": "Яагаад 5-ыг буюу бага тоог сонгосон бэ? Хамгийн бага харьцаа нь “бусад ямар ч шаардлагыг зөрчихгүйгээр энэ орцыг хамгийн ихдээ хэдийг хийж болох вэ?” гэдгийг зааж өгдөг. 5 кг тахианы мах хийхэд уургийн шаардлага (10 нэгж) яг таг 100% биелж дуусна. Харин төмөр 5 нэгжтэй л болж дутуу үлдэнэ. Энэ нь ямар ч дүрмийг зөрчихгүй бөгөөд менежерт “уургийн шаардлага хангагдлаа, тахианы махаа энд зогсоо; дутуу байгаа төмрөө өөр махаар, өөрөөр хэлбэл үхрийн махаар нөх” гэсэн маш ухаалаг эдийн засгийн дохиог өгч байгаа хэрэг юм."}, {"t": "h", "lvl": 3, "x": "6.6.6. Оновчлолын үе шатууд"}, {"t": "p", "x": "Итераци 1. Тахианы махыг ашиглаж эхлэх нь"}, {"t": "p", "x": "Тахианы махны мөрийг 2-т хувааж, бусад мөрийн харгалзах элементийг 0 болгоно."}, {"t": "table", "rows": [["Суурь", "x₁ (үхэр)", "x₂ (тахиа)", "s₁", "s₂", "Шийд (RHS)"], ["x₂ (тахиа)", "0.5", "1", "−0.5", "0", "5"], ["A₂ (торгууль 2)", "1.5", "0", "0.5", "−1", "3"], ["Z (зардал)", "1.5M − 3.5", "0", "0.5M − 1.5", "−M", "3M + 15"]]}, {"t": "p", "x": "Эдийн засгийн тайлбар: 5 кг тахианы мах хийснээр уургийн шаардлагыг бүрэн хангаж чадсан тул уургийн торгуулиас (A₁) салсан. Гэхдээ тахианы маханд төмөр бага байдаг тул төмрийн шаардлага хараахан хангагдаагүй, A₂ торгууль хэвээр байна."}, {"t": "p", "x": "Үйлдэл: зардлын мөрөнд үхрийн мах (x₁) дээр 1.5M − 3.5 гэсэн эерэг тоо үлдсэн нь одоо үхрийн мах нэмж, төмрийн дутагдлыг нөхөх цаг болсныг илтгэж байна. Тиймээс үхрийн мах (x₁) суурьт орж, үлдсэн сүүлчийн торгууль (A₂) гарна."}, {"t": "p", "x": "Орох хувьсагч (Pivot Column): тахианы мах (x₂)"}, {"t": "p", "x": "Бид зардлыг багасгах бодлого бодож байгаа тул Z мөрөн дэх хамгийн их эерэг тоотой баганыг сонгоно."}, {"t": "p", "x": "Үхрийн мах (x₁): 3M − 5"}, {"t": "p", "x": "Тахианы мах (x₂): 3M − 3"}, {"t": "p", "x": "M бол асар том тоо тул 3M − 3 нь илүү том утга юм. Иймд тахианы мах (x₂) үйлдвэрлэл рүү буюу суурьт орно."}, {"t": "p", "x": "Гарах хувьсагч (Ratio Test):"}, {"t": "p", "x": "Тахианы махны (x₂) баганын тоонууд дээрээсээ доош 2 болон 1 байна. Эдгээрт шийдийн (RHS) баганын тоонуудыг хувааж харьцуулна:"}, {"t": "p", "x": "1-р мөр (A₁ зохиомол хувьсагч): 10/2 = 5 (хамгийн бага харьцаа)"}, {"t": "p", "x": "2-р мөр (A₂ зохиомол хувьсагч): 8/1 = 8"}, {"t": "p", "x": "Дүгнэлт: хамгийн бага харьцаатай 1-р мөрийн A₁ гарч, оронд нь тахианы мах x₂ орно. Огтлолцол дээрх 2 гэсэн тоо бидний гол элемент (Pivot) боллоо."}, {"t": "p", "x": "Хүснэгтийн хувиргалт (Гаусс-Жорданы үйлдэл)"}, {"t": "p", "x": "Шинэ гол мөр (шинэ x₂ буюу тахианы махны мөр):"}, {"t": "p", "x": "Хуучин 1-р мөрийн бүх элементийг гол элемент болох 2-т хуваана."}, {"t": "p", "x": "x₁: 1/2 = 0.5"}, {"t": "p", "x": "x₂: 2/2 = 1"}, {"t": "p", "x": "s₁ (илүүдэл): −1/2 = −0.5"}, {"t": "p", "x": "s₂ (илүүдэл): 0/2 = 0"}, {"t": "p", "x": "Шийд (RHS): 10/2 = 5"}, {"t": "p", "x": "Шинэ 2-р мөрийг тооцох (хуучин A₂ мөр шинэчлэгдэх):"}, {"t": "p", "x": "Томьёо: шинэ R2 = хуучин R2 − (1) × шинэ гол мөр (энд үржигдэхүүн 1 байгаа нь хуучин x₂ баганын 2-р мөрийн тоо юм)."}, {"t": "p", "x": "x₁: 2 − 1(0.5) = 1.5"}, {"t": "p", "x": "x₂: 1 − 1(1) = 0"}, {"t": "p", "x": "s₁: 0 − 1(−0.5) = 0.5"}, {"t": "p", "x": "s₂: −1 − 1(0) = −1"}, {"t": "p", "x": "Шийд (RHS): 8 − 1(5) = 3"}, {"t": "p", "x": "Шинэ Z мөрийг тооцох (торгуулийг бууруулах нь):"}, {"t": "p", "x": "Томьёо: шинэ Z = хуучин Z − (3M − 3) × шинэ гол мөр"}, {"t": "p", "x": "x₁ дээр: (3M − 5) − (3M − 3)×0.5 = 3M − 5 − 1.5M + 1.5 = 1.5M − 3.5"}, {"t": "p", "x": "x₂ дээр: (3M − 3) − (3M − 3)×1 = 0"}, {"t": "p", "x": "s₁ дээр: (−M) − (3M − 3)×(−0.5) = −M + 1.5M − 1.5 = 0.5M − 1.5"}, {"t": "p", "x": "s₂ дээр: (−M) − (3M − 3)×0 = −M"}, {"t": "p", "x": "Шийд (RHS) дээр: 18M − (3M − 3)×5 = 18M − 15M + 15 = 3M + 15"}, {"t": "p", "x": "Итераци 2. Үхрийн махыг нэмж, эцсийн торгуулиас салах нь"}, {"t": "p", "x": "Итераци 1-ийн дараа бид эхний зохиомол хувьсагчаасаа салсан ч, хүснэгтэд A₂ гэсэн дахин нэг зохиомол хувьсагч үлдсэн байна. Одоо Итераци 2-оор түүнийг хөөж гаргаад, бодлогыг бүрэн дуусгах тооцооллыг алхам алхмаар нь харуулъя."}, {"t": "p", "x": "Орох хувьсагч (Pivot Column): үхрийн мах (x₁)"}, {"t": "p", "x": "Итераци 1-ийн төгсгөлд Z мөрөнд x₁: 1.5M − 3.5, s₁: 0.5M − 1.5 гэсэн утга байсан. Бид зардлыг багасгах (Min) бодлого бодож байгаа тул хамгийн их эерэг тоог сонгоно. 1.5M нь 0.5M-ээс хамаагүй том тул үхрийн мах (x₁) үйлдвэрлэл рүү орно."}, {"t": "p", "x": "Гарах хувьсагч (Ratio Test):"}, {"t": "p", "x": "Одоо x₁ баганын тоонуудад (0.5 болон 1.5) шийдийн (RHS) баганын тоонуудыг хуваана:"}, {"t": "p", "x": "1-р мөр (x₂, тахианы мах): 5/0.5 = 10"}, {"t": "p", "x": "2-р мөр (A₂ зохиомол хувьсагч): 3/1.5 = 2 (хамгийн бага)"}, {"t": "p", "x": "Дүгнэлт: хамгийн бага харьцаа гарсан тул эцсийн зохиомол хувьсагч болох A₂ хүснэгтээс бүрмөсөн гарч, оронд нь үхрийн мах (x₁) орно. Огтлолцол дээрх 1.5 гэсэн тоо бидний гол элемент (Pivot) боллоо."}, {"t": "p", "x": "Хүснэгтийн хувиргалт (эцсийн шат)"}, {"t": "p", "x": "Шинэ гол мөр (шинэ x₁ буюу үхрийн махны мөр):"}, {"t": "p", "x": "Хуучин 2-р мөрийн бүх элементийг гол элемент болох 1.5-д хуваана (тооцооллыг нарийвчлахын тулд энгийн бутархайгаар бичье):"}, {"t": "p", "x": "x₁: 1.5/1.5 = 1"}, {"t": "p", "x": "x₂: 0/1.5 = 0"}, {"t": "p", "x": "s₁: 0.5/1.5 = 1/3"}, {"t": "p", "x": "s₂: −1/1.5 = −2/3"}, {"t": "p", "x": "Шийд (RHS): 3/1.5 = 2"}, {"t": "p", "x": "Шинэ 1-р мөрийг тооцох (хуучин x₂ мөр шинэчлэгдэх):"}, {"t": "p", "x": "Томьёо: шинэ R1 = хуучин R1 − (0.5) × шинэ гол мөр"}, {"t": "p", "x": "x₁: 0.5 − 0.5(1) = 0"}, {"t": "p", "x": "x₂: 1 − 0.5(0) = 1"}, {"t": "p", "x": "s₁: −0.5 − 0.5(1/3) = −1/2 − 1/6 = −2/3"}, {"t": "p", "x": "s₂: 0 − 0.5(−2/3) = 0 + 1/3 = 1/3"}, {"t": "p", "x": "Шийд (RHS): 5 − 0.5(2) = 5 − 1 = 4"}, {"t": "p", "x": "Эцсийн Z мөрийг тооцох (бодит зардлаа олох):"}, {"t": "p", "x": "Бүх зохиомол хувьсагч, тэдгээрийн M торгууль устсан тул Z мөрийг олох нь маш хялбар болно. Бид Zⱼ − Cⱼ = ∑(Cᵦ × aᵢⱼ) − Cⱼ гэсэн үндсэн томьёогоо ашиглаад, Cᵦ буюу суурьт байгаа x₁ (5₮), x₂ (3₮)-ийн бодит үнийг орлуулан шууд бодно."}, {"t": "p", "x": "x₁ дээр: (3×0) + (5×1) − 5 = 0"}, {"t": "p", "x": "x₂ дээр: (3×1) + (5×0) − 3 = 0"}, {"t": "p", "x": "s₁ дээр: (3×(−2/3)) + (5×1/3) − 0 = −2 + 5/3 = −1/3"}, {"t": "p", "x": "s₂ дээр: (3×1/3) + (5×(−2/3)) − 0 = 1 − 10/3 = −7/3"}, {"t": "p", "x": "Эцсийн шийд (RHS буюу нийт зардал): (3₮ × 4 ширхэг) + (5₮ × 2 ширхэг) = 12 + 10 = 22₮"}, {"t": "p", "x": "Эцсийн хүснэгт: төгс жор олдсон нь (оновчтой шийд)"}, {"t": "p", "x": "A₂ байсан мөрийг 1.5-д хувааж 1 болгоод, дээд мөрийн харгалзах элементийг 0 болгоно. Одоо M бүрэн устлаа."}, {"t": "table", "rows": [["Суурь", "x₁ (үхэр)", "x₂ (тахиа)", "s₁", "s₂", "Шийд (RHS)"], ["x₂ (тахиа)", "0", "1", "−0.67", "0.33", "4"], ["x₁ (үхэр)", "1", "0", "0.33", "−0.67", "2"], ["Z (зардал)", "0", "0", "−0.33", "−2.33", "22"]]}, {"t": "p", "x": "Z мөрөнд ямар ч эерэг (+) тоо үлдээгүй. Торгуулиуд арилж, бодолт зогслоо."}, {"t": "p", "x": "Оновчтой шийд олдсон эсэхийг шалгах: зардлыг хамгийн бага байлгах (Minimization) бодлогын хувьд Z мөрөн дэх бүх тоо тэг эсвэл сөрөг утгатай болсон үед бодолт дуусдаг. Бидний Z мөрийн тоонууд (0, 0, −1/3, −7/3) бүгд энэ шаардлагыг хангасан тул энэ бол хамгийн шилдэг буюу оновчтой шийд мөн байна."}, {"t": "p", "x": "Ингээд компани бүх M торгуулиасаа бүрэн салав. Эцсийн оновчтой шийдээр бол зардлаа хамгийн бага түвшинд барихын тулд 4 нэгж тахианы мах (x₂), 2 нэгж үхрийн мах (x₁) худалдан авах ёстой бөгөөд үүнд гарах хамгийн доод зардал 22₮ болно."}, {"t": "h", "lvl": 3, "x": "6.6.7. Оновчтой шийд"}, {"t": "p", "x": "Энэхүү эцсийн хүснэгтээс дараах дүгнэлтийг гаргаж авна:"}, {"t": "p", "x": "Хамгийн хямд “төгс” жор (үйлдвэрлэлийн шийд)"}, {"t": "p", "x": "x₂ = 4: нэг багц хиаманд 4 кг тахианы мах орно."}, {"t": "p", "x": "x₁ = 2: нэг багц хиаманд 2 кг үхрийн мах орно."}, {"t": "p", "x": "Z = 22: энэхүү багцын нийт махны өртөг ердөө 22,000₮ болно. Энэ бол стандартыг хангаж чадах хамгийн хямд жор юм."}, {"t": "p", "x": "Бүх A = 0: аль ч зохиомол хувьсагч суурьт үлдээгүй тул шийд боломжит (Feasible) бөгөөд оновчтой (Optimal) мөн."}, {"t": "h", "lvl": 3, "x": "6.6.8. Эдийн засгийн тайлбар"}, {"t": "p", "x": "Илүүдэл шим тэжээл бий юу? (s₁ = 0, s₂ = 0)"}, {"t": "p", "x": "Хүснэгтийн суурь хэсэгт s₁, s₂ хоёулаа байхгүй байна."}, {"t": "p", "x": "Утга нь: бид хэрэглэгчдэд нэг ч грамм уураг, төмрийг илүүдэл болгож үнэгүй өгөөгүй. Шаардлага яг 10 болон 8 дээрээ таг таарсан байна. Компани зардлаа тултал нь хэмнэжээ."}, {"t": "p", "x": "Min бодлого буюу зардал бууруулах алгоритмыг орц найрлагын холимог (Blending), стандартын доод хязгаар, илүүдлээс үүсэх үргүй зардал гэсэн гурван ойлголттой холбож ойлговол хялбар болдог."}, {"t": "p", "x": "Тэмдэглэл: энэхүү бодлогын хувьд зорилгын функцийн коэффициент болон баруун гар талын утгын мэдрэмжийн шинжилгээг (сүүдрийн үнэ, зөвшөөрөгдөх муж) Бүлэг 5.6-т үзсэн аргачлалаар яг адилхан хийж болно — энд давхардуулан үзэхгүй."}, {"t": "h", "lvl": 2, "x": "6.7. Хоёр үе шатны арга (Two-Phase Method) — товч"}, {"t": "h", "lvl": 3, "x": "6.7.1. Танилцуулга"}, {"t": "p", "x": "Big-M аргын сул тал бол M-д ямар тоон утга өгөхөө сонгох шаардлагатай явдал юм: хэт жижиг M сонговол алгоритм зохиомол хувьсагчийг бүрэн хөөж чадахгүй байж болзошгүй, харин хэт том M сонговол компьютерийн тооцоололд тоон алдаа (rounding error) үүсэх эрсдэлтэй. Хоёр үе шатны арга (Two-Phase Method) энэ асуудлаас бүрмөсөн ангид, учир нь M гэсэн тэмдэглэгээг огт ашиглахгүй."}, {"t": "h", "lvl": 3, "x": "6.7.2. Үе шат 1: зохиомол хувьсагчийг минимумчлах"}, {"t": "p", "x": "Каноник хэлбэрт оруулсны дараа анхны буюу жинхэнэ зорилгын функцийг түр орхиод, зөвхөн зохиомол хувьсагчдын нийлбэрийг симплекс аргаар минимумчилна:"}, {"t": "p", "x": "min W = A₁ + A₂ + ... + Aₙ"}, {"t": "p", "x": "Хэрэв Үе шат 1-ийн оновчтой шийд дээр W = 0 бол, өөрөөр хэлбэл бүх Aᵢ = 0 бол бодлого боломжит (Feasible) бөгөөд Үе шат 2 рүү шилжинэ. Харин W > 0 хэвээр үлдвэл бодлого шийдгүй (Infeasible) гэдгийг тэр даруй тодорхойлно. Big-M аргад бодолтыг эцэс хүртэл явуулж байж мэддэг байсан бол, хоёр үе шатны арга үүнийг Үе шат 1 дээрээ илрүүлдэг."}, {"t": "h", "lvl": 3, "x": "6.7.3. Үе шат 2: жинхэнэ зорилгын функцээр симплекс"}, {"t": "p", "x": "Үе шат 1-ийн эцсийн хүснэгтээс (зохиомол хувьсагчдын баганыг хассан) суурийг өвлөн авч, жинхэнэ зорилгын функцийг (жишээ нь Z = 5x₁ + 3x₂) сэргээгээд, Бүлэг 5-т үзсэн энгийн симплекс алгоритмаар үргэлжлүүлж бодно."}, {"t": "h", "lvl": 3, "x": "6.7.4. Big-M ба хоёр үе шатны аргын харьцуулалт"}, {"t": "table", "rows": [["Шинж чанар", "Big-M арга", "Хоёр үе шатны арга"], ["Тооцооллын үе шат", "1 (нэг удаагийн)", "2 (тусдаа)"], ["M-ийн тоон утга", "Сонгох шаардлагатай", "Огт ашиглахгүй"], ["Гараар бодоход", "Илүү энгийн, ойлгомжтой", "Арай урт боловч тодорхой"], ["Программчлалд", "Тоон алдааны эрсдэлтэй", "Илүү тохиромжтой, тогтвортой"], ["Сурган хүмүүжүүлэх ач холбогдол", "Эдийн засгийн “торгууль” зарчмыг тод харуулдаг", "Боломжит ба оновчтой шийдийг тусад нь ойлгоход тус болдог"]]}, {"t": "p", "x": "Энэ сурах бичигт цаашид Big-M аргыг үндсэн арга болгон ашиглана. Хоёр үе шатны аргыг мэдэж байх нь программ хангамжийн, тухайлбал Excel Solver-ийн дотоод алгоритмын зарим онцлогийг ойлгоход тустай."}, {"t": "h", "lvl": 2, "x": "6.8. Кейс: хөдөө аж ахуйн диетийн бодлого (ХААИС онцлог)"}, {"t": "p", "x": "“Хиам” ХХК-ийн жишээнээс өөр, хөдөө аж ахуйн салбарын диетийн бодлого авч үзье: малын тэжээлийн найрлагыг оновчлох асуудал."}, {"t": "h", "lvl": 3, "x": "6.8.1. Бизнесийн нөхцөл"}, {"t": "p", "x": "“Алтан Тал” фермийн мал аж ахуй өвлийн улиралд малынхаа тэжээлийн холимогийг хоёр төрлийн түүхий эдээс — Тэжээл А (x₁) ба Тэжээл Б (x₂) — бэлддэг. Фермийн технологич уураг, тос, эрдэс бодисын доод шаардлагыг хангахын зэрэгцээ тэжээлийн нийт өртгийг хамгийн бага байлгахыг зорьж байна."}, {"t": "p", "x": "Тэжээл А-гийн үнэ: 3,000₮/кг (C₁ = 3)"}, {"t": "p", "x": "Тэжээл Б-гийн үнэ: 2,000₮/кг (C₂ = 2)"}, {"t": "p", "x": "Тэжээлийн найрлагын шаардлага (нэг нэгж холимогт байх доод хязгаар):"}, {"t": "table", "rows": [["Шим тэжээл", "Тэжээл А (нэгж/кг)", "Тэжээл Б (нэгж/кг)", "Доод шаардлага"], ["Уураг", "1", "1", "≥ 10"], ["Тос", "1", "2", "≥ 10"], ["Эрдэс бодис", "2", "1", "≥ 12"]]}, {"t": "h", "lvl": 3, "x": "6.8.2. Бодлогын тавилт"}, {"t": "p", "x": "Хувьсагч: x₁ = Тэжээл А-гийн хэмжээ (кг), x₂ = Тэжээл Б-гийн хэмжээ (кг)"}, {"t": "p", "x": "Z = 3x₁ + 2x₂ → min"}, {"t": "p", "x": "1x₁ + 1x₂ ≥ 10   (уураг)"}, {"t": "p", "x": "1x₁ + 2x₂ ≥ 10   (тос)"}, {"t": "p", "x": "2x₁ + 1x₂ ≥ 12   (эрдэс бодис)"}, {"t": "p", "x": "x₁, x₂ ≥ 0"}, {"t": "h", "lvl": 3, "x": "6.8.3. Каноник хэлбэрт оруулах"}, {"t": "p", "x": "Гурван хязгаарлалт бүгд ≥ тэмдэгтэй тул Бүлэг 6.2.3-т үзсэн дүрмээр −S болон +A хоёуланг нь нэмнэ:"}, {"t": "p", "x": "x₁ + x₂ − s₁ + A₁ = 10"}, {"t": "p", "x": "x₁ + 2x₂ − s₂ + A₂ = 10"}, {"t": "p", "x": "2x₁ + x₂ − s₃ + A₃ = 12"}, {"t": "p", "x": "Зорилго:  Z = 3x₁ + 2x₂ + MA₁ + MA₂ + MA₃ → min"}, {"t": "h", "lvl": 3, "x": "6.8.4. Big-M аргаар шийдэх нь"}, {"t": "p", "x": "Гурван зохиомол хувьсагчтай тул “Хиам” ХХК-ийн жишээнээс арай урт буюу гурван итерацитай боловч, ашиглах логик бүрэн ижил юм. Симплекс хүснэгтийг Бүлэг 6.6-тай адил форматаар харуулъя (A баганыг тусад нь харуулалгүй, мөрийн нэрээр илэрхийлнэ)."}, {"t": "p", "x": "Анхны хүснэгт"}, {"t": "table", "rows": [["Суурь", "x₁ (А)", "x₂ (Б)", "s₁", "s₂", "s₃", "RHS", "Харьцаа"], ["A₁ (уураг)", "1", "1", "−1", "0", "0", "10", "10/1 = 10"], ["A₂ (тос)", "1", "2", "0", "−1", "0", "10", "10/2 = 5"], ["A₃ (эрдэс)", "2", "1", "0", "0", "−1", "12", "12/1 = 12"], ["Z", "4M − 3", "4M − 2", "−M", "−M", "−M", "32M", ""]]}, {"t": "p", "x": "Орох хувьсагч: x₂ (4M − 2 нь x₁-ийн 4M − 3-аас том). Гарах хувьсагч: A₂ (харьцаа 5 нь хамгийн бага). Гол элемент = 2."}, {"t": "p", "x": "Итераци 1 (суурь: A₁, x₂, A₃)"}, {"t": "table", "rows": [["Суурь", "x₁ (А)", "x₂ (Б)", "s₁", "s₂", "s₃", "RHS", "Харьцаа"], ["A₁", "1/2", "0", "−1", "1/2", "0", "5", "5/(1/2) = 10"], ["x₂ (Б)", "1/2", "1", "0", "−1/2", "0", "5", "5/(1/2) = 10"], ["A₃", "3/2", "0", "0", "1/2", "−1", "7", "7/(3/2) = 14/3"], ["Z", "2M − 2", "0", "−M", "M − 1", "−M", "12M + 10", ""]]}, {"t": "p", "x": "Орох хувьсагч: x₁ (2M − 2 нь s₂-ийн M − 1-ээс том). Гарах хувьсагч: A₃ (харьцаа 14/3 ≈ 4.67 нь хамгийн бага). Гол элемент = 3/2."}, {"t": "p", "x": "Итераци 2 (суурь: A₁, x₂, x₁)"}, {"t": "table", "rows": [["Суурь", "x₁ (А)", "x₂ (Б)", "s₁", "s₂", "s₃", "RHS", "Харьцаа"], ["A₁", "0", "0", "−1", "1/3", "1/3", "8/3", "8"], ["x₂ (Б)", "0", "1", "0", "−2/3", "1/3", "8/3", "—"], ["x₁ (А)", "1", "0", "0", "1/3", "−2/3", "14/3", "14"], ["Z", "0", "0", "−M", "(1/3)M − 1/3", "(1/3)M − 4/3", "(8/3)M + 58/3", ""]]}, {"t": "p", "x": "Орох хувьсагч: s₂ ((1/3)M − 1/3 нь s₃-ийн (1/3)M − 4/3-аас том, учир нь −1/3 > −4/3). Гарах хувьсагч: A₁ (харьцаа 8 нь хамгийн бага). Гол элемент = 1/3."}, {"t": "p", "x": "Эцсийн хүснэгт (суурь: s₂, x₂, x₁) — оновчтой шийд"}, {"t": "table", "rows": [["Суурь", "x₁ (А)", "x₂ (Б)", "s₁", "s₂", "s₃", "RHS"], ["s₂", "0", "0", "−3", "1", "1", "8"], ["x₂ (Б)", "0", "1", "−2", "0", "1", "8"], ["x₁ (А)", "1", "0", "1", "0", "−1", "2"], ["Z", "0", "0", "−1", "0", "−1", "22"]]}, {"t": "p", "x": "Z мөрөнд ямар ч эерэг (+) тоо, ямар ч M-ийн коэффициент үлдээгүй тул бодолт зогслоо — оновчтой шийд олдлоо. Ажиглавал, эхний хүснэгтэд уургийн мөрөнд байсан зохиомол хувьсагч A₁-ийн оронд эцсийн хүснэгтэд тосны илүүдэл хувьсагч s₂ суурьт орж ирснийг харж болно — энэ нь тосны шаардлага илүүдэлтэй биелсэн гэсэн эдийн засгийн дохио юм."}, {"t": "h", "lvl": 3, "x": "6.8.5. Эцсийн хариу ба эдийн засгийн тайлбар"}, {"t": "p", "x": "x₁ = 2: нэг нэгж тэжээлийн холимогт 2 кг Тэжээл А орно."}, {"t": "p", "x": "x₂ = 8: нэг нэгж тэжээлийн холимогт 8 кг Тэжээл Б орно."}, {"t": "p", "x": "Z = 22: нийт тэжээлийн өртөг 22,000₮ буюу хамгийн бага зардал болно."}, {"t": "p", "x": "s₂ = 8: тосны агууламж шаардлагаас 8 нэгжээр илүү гарсан (Surplus). Энэ нь муу зүйл биш, зүгээр л уг нөөц хязгаарлагч хүчин зүйл (Bottleneck) биш гэсэн үг."}, {"t": "p", "x": "s₁ = 0, s₃ = 0: уураг болон эрдэс бодисын шаардлага яг тэнцүү хэмжээгээр (10 ба 12 нэгж) биелсэн — ферм эдгээр хоёр нөөцийг бүрэн дүүрэн ашигласан байна."}, {"t": "h", "lvl": 3, "x": "6.8.6. Практик хэрэглээ"}, {"t": "p", "x": "Энэ төрлийн тэжээлийн блендингийн (Feed-Mix) бодлогыг фермерүүд, тэжээлийн үйлдвэрүүд өдөр тутам ашигладаг бөгөөд Excel Solver дээр ижил аргачлалаар маш хурдан бодож болно (→ Хавсралт Б.5-д үзнэ үү). Мал аж ахуйн технологичид үнэ ханшийн өөрчлөлт гарах бүрд ижил загварыг дахин бодож, хамгийн хямд “жор”-оо тухай бүр шинэчилдэг."}, {"t": "h", "lvl": 2, "x": "Бүлгийн хураангуй"}, {"t": "p", "x": "Энэ бүлэгт бид Бүлэг 5-т үзсэн симплекс алгоритмын өргөтгөл болох Big-M аргыг үзлээ. ≥ болон = хязгаарлалттай бодлогуудыг каноник хэлбэрт оруулахдаа илүүдэл хувьсагч (−S) болон зохиомол хувьсагч (+A) хэрхэн ялгаатай үүрэг гүйцэтгэдгийг тодруулж, зохиомол хувьсагч нь “жинхэнэ” бус, зөвхөн симплекс алгоритмыг эхлүүлэх зорилготой түр хэрэглүүр гэдгийг тайлбарлав. M гэдэг маш том тоо нь энэхүү зохиомол хувьсагчийг оновчтой шийдээс албадан хөөх торгуулийн үүрэг гүйцэтгэдэг бөгөөд Min бодлогод +M, Max бодлогод −M тэмдэгтэйгээр орно."}, {"t": "p", "x": "“Хиам” ХХК-ийн орц найрлагын бодлогыг Big-M аргаар бүрэн шийдэж, анхны хүснэгт байгуулахаас эхлээд Z мөрийн тооцооллын томьёо (Zⱼ − Cⱼ = ∑(Cᵦ×aᵢⱼ) − Cⱼ), орох ба гарах хувьсагчийн сонголтын эдийн засгийн логик (Bottleneck зарчим), Гаусс-Жорданы мөрийн үйлдэл, эцэст нь оновчтой шийдийг олох хүртэлх бүх алхмыг дараалан харуулав. Хөдөө аж ахуйн тэжээлийн блендингийн кейсээр энэ мэдлэгээ бататгаж, гурван ≥ хязгаарлалттай илүү төвөгтэй бодлогыг мөн бүрэн шийдэв."}, {"t": "p", "x": "Эцэст нь хоёр үе шатны аргыг товч танилцуулж, Big-M аргатай харьцуулав. Энэ бүлгийг сайн ойлгосон уншигч одоо ≤, ≥, = холилдсон дурын хязгаарлалттай шугаман программчлалын бодлогыг симплекс аргаар бодох чадвартай боллоо — энэ бол Бүлэг 7-т үзэх хосмог бодлогын (Duality) суурь мэдлэг мөн юм."}, {"t": "h", "lvl": 2, "x": "Дасгал ажил"}, {"t": "h", "lvl": 3, "x": "Хялбар (2 ширхэг)"}, {"t": "p", "x": "Дасгал 1. Дараах хязгаарлалтуудыг каноник хэлбэрт оруул. Ямар хувьсагч нэмэх ёстой вэ?"}, {"t": "p", "x": "2x₁ + 3x₂ ≤ 100"}, {"t": "p", "x": "x₁ + 4x₂ ≥ 50"}, {"t": "p", "x": "5x₁ + x₂ = 30"}, {"t": "p", "x": "Дасгал 2. Гурван төрлийн хувьсагчийн (+S, −S, +A) эдийн засгийн утгыг тайлбарла. Ялгааг нь харуул."}, {"t": "h", "lvl": 3, "x": "Дунд зэрэг (4 ширхэг)"}, {"t": "p", "x": "Дасгал 3. Дараах min бодлогыг Big-M аргаар бод:"}, {"t": "p", "x": "min Z = 3x₁ + 2x₂"}, {"t": "p", "x": "x₁ + 2x₂ ≥ 10"}, {"t": "p", "x": "3x₁ + x₂ ≥ 15"}, {"t": "p", "x": "x₁, x₂ ≥ 0"}, {"t": "p", "x": "Дасгал 4. Диетийн бодлого — хоёр хоол (x₁, x₂), гурван шим тэжээл (уураг, витамин, эрдэс). Big-M аргаар шийд:"}, {"t": "p", "x": "min Z = 6x₁ + 4x₂"}, {"t": "p", "x": "2x₁ + x₂ ≥ 12   (уураг)"}, {"t": "p", "x": "x₁ + 2x₂ ≥ 12   (витамин)"}, {"t": "p", "x": "x₁ + x₂ ≥ 5   (эрдэс)"}, {"t": "p", "x": "x₁, x₂ ≥ 0"}, {"t": "p", "x": "Дасгал 5. Холимог хязгаарлалттай (≤, ≥, =) бодлого. Big-M аргаар шийд:"}, {"t": "p", "x": "min Z = 3x₁ + 2x₂"}, {"t": "p", "x": "x₁ + x₂ ≤ 20"}, {"t": "p", "x": "x₁ + 3x₂ ≥ 15"}, {"t": "p", "x": "x₁ + x₂ = 10"}, {"t": "p", "x": "x₁, x₂ ≥ 0"}, {"t": "p", "x": "Дасгал 6. Хөдөө аж ахуйн тэжээлийн бодлого. Малын тэжээлийн найрлагыг сонгох (Бүлэг 6.8-тай төстэй, өөр тоотой):"}, {"t": "p", "x": "min Z = 5x₁ + 4x₂"}, {"t": "p", "x": "x₁ + x₂ ≥ 8"}, {"t": "p", "x": "2x₁ + x₂ ≥ 10"}, {"t": "p", "x": "x₁, x₂ ≥ 0"}, {"t": "h", "lvl": 3, "x": "Төвөгтэй (2 ширхэг)"}, {"t": "p", "x": "Дасгал 7. Гурван хувьсагчтай, олон хязгаарлалттай (≤, ≥, =) бодлого. Big-M аргаар бүрэн шийд:"}, {"t": "p", "x": "min Z = 2x₁ + 3x₂ + 4x₃"}, {"t": "p", "x": "x₁ + x₂ + x₃ ≤ 20"}, {"t": "p", "x": "x₁ + 2x₂ + x₃ ≥ 10"}, {"t": "p", "x": "x₁ + x₂ − x₃ = 2"}, {"t": "p", "x": "x₁, x₂, x₃ ≥ 0"}, {"t": "p", "x": "Дасгал 8. Бодлого шийдгүй байх магадлалыг шалгах дасгал. Уншигч оновчтой шийдэд A > 0 гарсныг илрүүлэх ёстой:"}, {"t": "p", "x": "min Z = x₁ + x₂"}, {"t": "p", "x": "x₁ + x₂ ≤ 4"}, {"t": "p", "x": "x₁ + x₂ ≥ 10"}, {"t": "p", "x": "x₁, x₂ ≥ 0"}, {"t": "h", "lvl": 2, "x": "Хариу түлхүүр"}, {"t": "p", "x": "Дасгал 1: 2x₁+3x₂≤100 → 2x₁+3x₂+s₁=100 (+S);  x₁+4x₂≥50 → x₁+4x₂−s₂+A₁=50 (−S ба +A);  5x₁+x₂=30 → 5x₁+x₂+A₂=30 (+A)"}, {"t": "p", "x": "Дасгал 2: Бүлэг 6.3-ыг үз — +S: ашиглагдаагүй нөөц (≤); −S: шаардлагаас давсан илүүдэл (≥); +A: жинхэнэ бус, зөвхөн симплекс аргыг эхлүүлэх зохиомол хэрэглүүр (≥, =)."}, {"t": "p", "x": "Дасгал 3: x₁ = 4, x₂ = 3, Z = 18."}, {"t": "p", "x": "Дасгал 4: x₁ = 4, x₂ = 4, Z = 40 (эрдэс бодисын хязгаарлалт 5 ≤ x₁+x₂ = 8 тул илүүдэлтэй биелнэ)."}, {"t": "p", "x": "Дасгал 5: x₁ = 0, x₂ = 10, Z = 20."}, {"t": "p", "x": "Дасгал 6: x₁ = 2, x₂ = 6, Z = 34."}, {"t": "p", "x": "Дасгал 7: x₁ = 0, x₂ = 4, x₃ = 2, Z = 20."}, {"t": "p", "x": "Дасгал 8: бодлого шийдгүй (Infeasible). x₁+x₂ нэгэн зэрэг ≤ 4 болон ≥ 10 байх боломжгүй тул эцсийн хүснэгтэд зохиомол хувьсагч A > 0 хэвээр үлдэнэ — энэ нь Бүлэг 6.5.6-д үзсэн “тусгай шалгалт”-ын яг тохиолдол юм."}]};
